from __future__ import annotations
from itertools import combinations
from typing import Dict, List, Sequence, Tuple

Matrix = List[List[float]]
Graph = Dict[int, set]

def make_graph(n: int, edges: Sequence[Tuple[int, int]]) -> Graph:
    g: Graph = {v: set() for v in range(n)}
    for u, v in edges:
        g[u].add(v); g[v].add(u)
    return g

def complete_graph(n: int) -> Graph:
    return make_graph(n, list(combinations(range(n), 2)))

def adjacency(g: Graph) -> Matrix:
    n = len(g); a = [[0.0]*n for _ in range(n)]
    for u in range(n):
        for v in g[u]:
            a[u][v] = 1.0
    return a

def mat_mul(a: Matrix, b: Matrix) -> Matrix:
    n = len(a); a2 = [[0.0]*n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if a[i][k]:
                for j in range(n):
                    a2[i][j] += a[i][k]*b[k][j]
    return a2

def trace(a: Matrix) -> float:
    return sum(a[i][i] for i in range(len(a)))

def edges(g: Graph) -> int:
    return sum(len(s) for s in g.values())//2

def triangles(g: Graph) -> int:
    n = len(g)
    return sum(1 for u, v, w in combinations(range(n), 3)
               if v in g[u] and w in g[u] and w in g[v])

for n in (3, 4, 5):
    g = complete_graph(n); a = adjacency(g)
    a2 = mat_mul(a, a); a3 = mat_mul(a2, a)
    m, t = edges(g), triangles(g)
    print(f"K_{n}: tr(A^2)={trace(a2):.0f} 2m={2*m}  "
          f"tr(A^3)={trace(a3):.0f} 6t={6*t}")

from __future__ import annotations
import math, random
from itertools import combinations
from typing import Dict, List, Sequence, Tuple

Matrix = List[List[float]]
Graph = Dict[int, set]

def erdos_renyi(n: int, p: float, rng: random.Random) -> Graph:
    g: Graph = {v: set() for v in range(n)}
    for u, v in combinations(range(n), 2):
        if rng.random() < p:
            g[u].add(v); g[v].add(u)
    return g

def adjacency(g: Graph) -> Matrix:
    n = len(g); a = [[0.0]*n for _ in range(n)]
    for u in range(n):
        for v in g[u]:
            a[u][v] = 1.0
    return a

def eigenvalues(a: Matrix, sweeps: int = 60) -> List[float]:
    n = len(a); m = [r[:] for r in a]
    for _ in range(sweeps):
        for p in range(n):
            for q in range(p+1, n):
                if abs(m[p][q]) < 1e-14: continue
                th = (m[q][q]-m[p][p])/(2*m[p][q])
                s0 = 1.0 if th >= 0 else -1.0
                tt = s0/(abs(th)+math.sqrt(th*th+1)); c = 1/math.sqrt(tt*tt+1); s = tt*c
                for k in range(n):
                    mkp, mkq = m[k][p], m[k][q]
                    m[k][p] = c*mkp - s*mkq; m[k][q] = s*mkp + c*mkq
                for k in range(n):
                    mpk, mqk = m[p][k], m[q][k]
                    m[p][k] = c*mpk - s*mqk; m[q][k] = s*mpk + c*mqk
    return [m[i][i] for i in range(n)]

def invariants(g: Graph) -> Tuple[float, int, int]:
    a = adjacency(g); ev = eigenvalues(a)
    lam = max(abs(x) for x in ev)
    m = sum(len(s) for s in g.values())//2
    n = len(g)
    t = sum(1 for u, v, w in combinations(range(n), 3)
            if v in g[u] and w in g[u] and w in g[v])
    return lam, m, t

def run(trials: int = 200, n: int = 12, p: float = 0.5) -> None:
    rng = random.Random(2026); ok = 0; ratios = []
    for _ in range(trials):
        lam, m, t = invariants(erdos_renyi(n, p, rng))
        q = lam*lam - m
        if lam*q <= 3*t + 1e-6:
            ok += 1
        if lam*q > 1e-6:
            ratios.append(3*t/(lam*q))
    print(f"lambda*q <= 3t held in {ok}/{trials} trials")
    if ratios:
        print(f"mean slack ratio 3t/(lambda*q) = {sum(ratios)/len(ratios):.3f}")

run()

from __future__ import annotations
from collections import Counter
from itertools import combinations, permutations
from typing import Dict, Sequence, Tuple

Graph = Dict[int, set]

def make_graph(n: int, edges: Sequence[Tuple[int, int]]) -> Graph:
    g: Graph = {v: set() for v in range(n)}
    for u, v in edges:
        g[u].add(v); g[v].add(u)
    return g

def closed_3walks(g: Graph):
    n = len(g)
    for u in range(n):
        for v in g[u]:
            for w in g[v]:
                if u in g[w]:
                    yield (u, v, w)

def demo() -> None:
    # A graph with two triangles sharing an edge: {0,1,2} and {1,2,3}.
    g = make_graph(4, [(0, 1), (0, 2), (1, 2), (1, 3), (2, 3)])
    walks = list(closed_3walks(g))
    groups = Counter(frozenset(w) for w in walks)
    print("distinct underlying vertex sets (triangles):", len(groups))
    for tri, cnt in groups.items():
        print(f"  triangle {set(tri)} -> {cnt} ordered closed walks")
    print("total closed 3-walks =", len(walks), "= 6 x", len(groups))
    # And the raw 3! = 6 fact:
    print("orderings of {5,6,7} =", len(set(permutations((5, 6, 7)))))

demo()

