from __future__ import annotations
from typing import List, Tuple

Matrix = List[List[float]]

def trace_counts(A: Matrix) -> Tuple[int, int]:
    """Return (edges, triangles) via m = tr(A^2)/2 and t = tr(A^3)/6."""
    n = len(A)
    A2: Matrix = [[0.0]*n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            aik = A[i][k]
            if aik:
                row = A[k]
                for j in range(n):
                    A2[i][j] += aik * row[j]
    m = sum(A2[i][i] for i in range(n)) / 2.0
    tr3 = 0.0
    for i in range(n):
        for j in range(n):
            tr3 += A[i][j] * A2[j][i]
    t = tr3 / 6.0
    return int(round(m)), int(round(t))

