from itertools import combinations
import matplotlib.pyplot as plt

def complete(n):
    a = [[0.0]*n for _ in range(n)]
    for u, v in combinations(range(n), 2):
        a[u][v] = a[v][u] = 1.0
    return a

def mul(a, b):
    n = len(a); c = [[0.0]*n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if a[i][k]:
                for j in range(n):
                    c[i][j] += a[i][k]*b[k][j]
    return c

def tr(a):
    return sum(a[i][i] for i in range(len(a)))

ns = list(range(2, 9)); tr2, m2, tr3, t6, qs = [], [], [], [], []
for n in ns:
    a = complete(n); a2 = mul(a, a); a3 = mul(a2, a)
    m = n*(n-1)//2; t = n*(n-1)*(n-2)//6
    tr2.append(tr(a2)); m2.append(2*m); tr3.append(tr(a3)); t6.append(6*t)
    qs.append((n-1)**2 - m)

fig, ax = plt.subplots(1, 2, figsize=(11,4))
ax[0].plot(ns, tr2, 'o-', label="tr(A^2)"); ax[0].plot(ns, m2, 'x--', label="2m")
