ax[0].set_xlabel("n"); ax[0].set_title("trace bridges for K_n"); ax[0].legend()
ax[1].plot(ns, qs, 'd-', color="purple"); ax[1].set_xlabel("n")
ax[1].set_title("spectral excess q of K_n")
